UPDATE companies SET description='EMSCO operates from Ashland, Virginia, providing on-demand electronics manufacturing services. The company focuses on scalable capacity without requiring customers to invest in infrastructure or additional personnel.

The company produces electrical wire and multi-conductor cable harnesses, printed circuit board assemblies, and electronic and mechanical box builds. Its processes include in-motion continuity testing and adherence to ISO 9001:2015-based procedures and IPC/WHMA-A 620 standards. EMSCO maintains $500,000 of standing raw inventory to reduce material lead times and offers stocking programs for rapid fulfillment.

EMSCO serves businesses throughout Virginia and the mid-Atlantic region, offering fast shipping and lower costs due to proximity, while also supporting customers across the United States as a domestic alternative to overseas production.

The company differentiates itself by doubling client capacity without added infrastructure costs, saving 10–50% on brand-name parts through bulk purchasing, and maintaining a near-zero voluntary attrition rate that preserves an experienced workforce.', certifications=ARRAY['ISO 9001:2015','IPC/WHMA-A 620']::text[], profile='{"capabilities": ["Wire harness assembly", "Multi-conductor cable harness assembly", "PCB assembly", "Box build assembly (electronic and mechanical)", "In-motion continuity testing", "Stocking programs", "Bulk procurement"], "industries": [], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Scalable capacity without new infrastructure or employees", "10\u201350% savings on brand-name parts through bulk ordering", "$500K standing raw inventory reducing lead times", "Near 0% voluntary attrition rate ensuring experienced workforce", "In-motion continuity testing with ISO 9001:2015 and IPC/WHMA-A 620 standards"], "facts_used": ["Location: Ashland, Virginia -> /", "Services: wire harnesses, PCB assemblies, box builds -> /", "Certifications: ISO 9001:2015, IPC/WHMA-A 620 -> /", "Standing inventory: $500K -> /", "Cost savings: 10-50% on brand-name parts via bulk ordering -> /", "Lead time reduction via stocking programs -> /", "Near 0% voluntary attrition rate -> /", "In-motion continuity testing -> /", "Serves Virginia, mid-Atlantic, and nationwide -> /", "Scalable capacity without investment -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "We manufacture things like electrical wire & multi-conductor cable harnesses, circuit board assemblies, electronic & mechanical box builds\u2014all on demand and right on time.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='emsco' AND approved AND profile IS NULL;
UPDATE companies SET description='EPD Electronics Inc. operates from Natrona Heights, Pennsylvania, where it has provided printed circuit board assembly and design services to the Western Pennsylvania region for over 30 years.

The facility houses surface mount and through-hole production lines supported by automated optical inspection, x-ray inspection, and circuit testing equipment. Beyond board-level assembly, EPD offers enclosure assembly, box build, final assembly, electro-mechanical integration, systems integration, and customer order fulfillment. The company also runs a climate-controlled warehouse for excess electronic components and provides 3D printing for prototyping.

EPD serves companies across the Western Pennsylvania region that need to bring new electronic products to market, from initial concept through prototype to full production. Its customer base includes firms requiring design engineering, PCB layout, and turnkey contract manufacturing.

